#include <bits/stdc++.h>
using namespace std;

#define ll long long
#define f(i, m, n)  for(int i = m; i<=n; i++)
#define rep(i, n)   for(int i =0; i<n; i++)

void solve(){
    int n; cin >> n;
    int N = 3*n;
    
    vector<ll> a(N+1);
    f(i, 1, N)  cin >> a[i];
    
    sort(a.begin()+1, a.end(), greater<ll>());
    
    vector<ll> pfx(N+1, 0);
    f(i, 1, N)  pfx[i] = pfx[i-1] + a[i];
    
    ll ans = 0;
    
    f(i, 0, n){
        int l = 1, r = n-i;
        int bk = 0;
        
        while(l <= r){
            int m = l + (r-l)/2;
            ll dif = a[i + 2*m -1] + a[i + 2*m] - 3LL*a[N - 2*i -m+1];
            
            if(dif > 0){
                bk = m;
                l = m+1;
            }
            else    r = m-1;
        }
        
        auto get_sc = [&](int k){
            return 2LL*pfx[i] + pfx[i+2*k] + 3LL*pfx[N - 2*i - k];
        };
        
        ans = max({ans, get_sc(0), get_sc(n-i), get_sc(bk)});

        if(bk + 1 <= n-i)   ans = max(ans, get_sc(bk+1));
    }
    
    cout << ans << "\n";
}

int main() {
	// your code goes here
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	
	ll t; cin >> t;
	while(t--){
	    solve();
	}
	
	return 0;

}
